"""Promote cooling-tower rows after original-PDF cell and route checks."""
import hashlib,json,subprocess,sys
from collections import Counter
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; sys.path.insert(0,str(ROOT)); PY=ROOT/".."/".."/".venv"/"Scripts"/"python.exe"
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 r=subprocess.run([str(PY),str(ROOT/"evals/check_cooling_tower_source_matrix.py")],cwd=ROOT,capture_output=True,text=True,encoding="utf8"); assert r.returncode==0,r.stderr[-1200:]; audit=json.loads(r.stdout.strip().splitlines()[-1]); assert audit["status"]=="pass" and audit["pdf_cells_compared"]==390 and audit["exact_runtime_routes"]==195
 from pipeline.validate_drafts import file_sha256,load_chunks,validate_one
