 idxp=ROOT/"data/drafts/executable.json"; idx=json.loads(idxp.read_text(encoding="utf8")); assert len(idx["executable"])==752 and len(idx["failed"])==130
 failed=next(f for f in idx["failed"] if f["id"]==key); assert failed["stage"]=="source_preflight"
 idx["failed"]=[f for f in idx["failed"] if f["id"]!=key]; idx["executable"]=sorted([*idx["executable"],key]); idx["summary"]["executable"]=len(idx["executable"]); idx["summary"]["failed"]=len(idx["failed"])
 idx["summary"]["by_calc_type"]["per_unit"]["attempted"]+=1; idx["summary"]["by_calc_type"]["per_unit"]["executable"]+=1; idx["summary"]["failure_reasons_top10"]=[list(x) for x in Counter(str(f.get("reason","")) for f in idx["failed"]).most_common(10)]; idxp.write_text(json.dumps(idx,ensure_ascii=False,indent=2)+"\n",encoding="utf8")
 rp=ROOT/"data/drafts/report.json"; report=json.loads(rp.read_text(encoding="utf8")); row=next(x for x in report["results"] if x["path"]=="specs\\기계설비\\8-1-3.json"); row["calc_type"]="per_unit"; row["format_issues"]=v["format_issues"]; row["citation_issues"]=v["citation_issues"]; row["ok"]=True; row["open_questions"]=len(package.get("open_questions",[])); report["ok"]=sum(bool(x["ok"]) for x in report["results"]); report["with_format_issues"]=sum(bool(x["format_issues"]) for x in report["results"]); report["with_citation_issues"]=sum(bool(x["citation_issues"]) for x in report["results"]); report["total_open_questions"]=sum(x["open_questions"] for x in report["results"]); rp.write_text(json.dumps(report,ensure_ascii=False,indent=2)+"\n",encoding="utf8")
 all_specs=sorted((ROOT/"data/drafts/specs").rglob("*.json")); manifest=hashlib.sha256(b"\n".join(p.relative_to(ROOT/"data/drafts/specs").as_posix().encode()+b"\0"+sha(p).encode() for p in all_specs)).hexdigest()
 evp=ROOT/"evals/runtime_validation/incremental-source-citation-checkpoint-2026-10-19.json"; ev=json.loads(evp.read_text(encoding="utf8")); ev["current_active_lists"]["executable"]=len(idx["executable"]); ev["current_active_lists"]["failed"]=len(idx["failed"]); ev["current_active_lists"]["failure_stages"]=dict(Counter(f["stage"] for f in idx["failed"])); ev["resolved"].append({"id":key,"common_cause":"side-by-side capacities × two labor trades: ODL duplicated the first trade row and dropped the special-labor row axis on all three continuation pages","checks":"independent PDF grid extraction and visual inspection of printed pp.690–692; 390 cells; 195 capacity×location×building routes; exact per-trade citations; calculation unit basis remains an explicit open question"}); ev["source_evidence_added_this_continuation"]["sections"]=3; ev["source_evidence_added_this_continuation"]["cells"]=416; ev["source_evidence_added_this_continuation"]["breakdown"]["기계설비/8-1-3"]=390; ev["hashes"]["spec_manifest_sha256"]=manifest; ev["hashes"]["chunks_sha256"]=sha(chunks_path); ev["hashes"]["executable_sha256"]=sha(idxp); ev["remaining_failures"]={"calculator_or_rule_gate":sum(f["stage"]=="calculator_execution_or_rule_gate" for f in idx["failed"]),"source_preflight":sum(f["stage"]=="source_preflight" for f in idx["failed"]),"format_preflight":sum(f["stage"]=="format_or_input_preflight" for f in idx["failed"]),"open_basis_policy":"8-1-3 unit is interpreted as 인/대 but the source table does not print an explicit per-tower basis; retained for review"}; evp.write_text(json.dumps(ev,ensure_ascii=False,indent=2)+"\n",encoding="utf8")
 print(json.dumps({"promoted":key,"audit":audit,"active_partition":{"executable":len(idx["executable"]),"failed":len(idx["failed"]),"unsupported":174,"excluded":2,"failure_stages":ev["current_active_lists"]["failure_stages"]},"report":{"ok":report["ok"],"citation_issues":report["with_citation_issues"]},"spec_manifest_sha256":manifest},ensure_ascii=False,indent=2))
